// INTERIM assets generated by scripts/build-wordmark.mjs from the supplied JPG (spectrum variant):
// "Jelly" is an alpha mask a moving neon gradient flows through; "Labs" keeps the original white.
// When JellyLabs-wordmark.svg arrives, split it the same way (or animate the SVG gradient directly).
// Reduced motion → the gradient holds still (see .wordmark rules in globals.css).

export function Wordmark({ className = "h-7" }: { className?: string }) {
  return (
    <span role="img" aria-label="Jelly Labs" className={`wordmark ${className}`}>
      <span aria-hidden="true" className="wordmark-jelly-wrap">
        <span className="wordmark-jelly absolute inset-0" />
      </span>
      {/* eslint-disable-next-line @next/next/no-img-element -- tiny pre-optimised layer; must align pixel-exact with the mask */}
      <img src="/brand/jellylabs-wordmark-labs.webp" alt="" width={640} height={151} decoding="async" />
    </span>
  );
}
